mapper.select:
/*selectSellerMpRqBulkQuotationProceState*/ SELECT ATOS_DATE, ATOS_END_DATE, STOA_DATE, STATUS, AGENT_TYPE_NAME, PROJECT_NAME, BUYER_NAME, BURQ_RFQ_NO, AGENT_DESCRIPTION, AGENT_SPECIFICATION, AGENT_MAKER_PART_NO, AGENT_MAKER_NAME, AGENT_MIN_ORDER_QTY, AGENT_PUR_UNIT_QTY, AGENT_UNIT_MEASURE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ09' AND CODE = AGENT_PROCESS_TYPE) AS AGENT_PROCESS_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ10' AND CODE = AGENT_PARCEL_YN) AS AGENT_PARCEL_YN, DECODE(AGENT_PROCESS_TYPE,1, (SELECT ADDRESS_LOC FROM ICOMCMPY WHERE COM_CODE = DELY_COM_CODE),2,(SELECT ADDRESS_LOC FROM ICOMCMPY WHERE COM_CODE = SM_WAREHOUSE_CODE AND STATUS <> 'D'),'-') AS DELY_TEXT, DELIVERY_LT, CH_LIST_PRICE, GIVEUP_REASEON, AGENT_REMARK, BUY_CLOSE_DATE, AGENT_MNG_USER_ID, (SELECT MIN(USER_NAME_LOC) FROM ICOMLUSR WHERE LEGACY_USER_ID = AGENT_MNG_USER_ID ) AS AGENT_MNG_USER_NAME FROM ( SELECT ATOS_DATE, ATOS_END_DATE, STOA_DATE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ04' AND CODE = STATUS) AS STATUS, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ03' AND CODE = AGENT_TYPE) AS AGENT_TYPE_NAME, PROJECT_NAME, DECODE( PROJECT_UNIT, 'B', (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = BUYER), (SELECT COMORG_NAME FROM BYCAORGL WHERE COMORG_CODE = BUYER) ) AS BUYER_NAME, BURQ_RFQ_NO, AGENT_DESCRIPTION, AGENT_SPECIFICATION, AGENT_MAKER_PART_NO, NVL((SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE= 'M104' AND CODE = AGENT_MAKER_CODE), AGENT_MAKER_CODE) AS AGENT_MAKER_NAME, AGENT_MIN_ORDER_QTY, AGENT_PUR_UNIT_QTY, AGENT_UNIT_MEASURE, AGENT_PROCESS_TYPE, AGENT_PARCEL_YN, DELIVERY_LT, CH_LIST_PRICE, DECODE(STATUS,'S2',AGENT_REMARK, '') AS GIVEUP_REASEON, DECODE(STATUS,'S2','', AGENT_REMARK) AS AGENT_REMARK, BUY_CLOSE_DATE, AGENT_MNG_USER_ID, SM_WAREHOUSE_CODE, DECODE( PROJECT_UNIT, 'B', BUYER, MAIN_BUYER ) AS DELY_COM_CODE FROM ( SELECT ATOS_DATE, ATOS_END_DATE, STOA_DATE, STATUS, AGENT_TYPE, PROJECT_NAME, PROJECT_UNIT, BURQ_RFQ_NO, AGENT_DESCRIPTION, AGENT_SPECIFICATION, AGENT_MAKER_PART_NO, AGENT_MAKER_CODE, AGENT_MIN_ORDER_QTY, AGENT_PUR_UNIT_QTY, AGENT_UNIT_MEASURE, AGENT_PROCESS_TYPE, AGENT_PARCEL_YN, SM_WAREHOUSE_CODE, DELIVERY_LT, CH_LIST_PRICE, BUY_CLOSE_DATE, AGENT_REMARK, F_SPLIT(ITEM_KEY_ID,'||',1) AS BUYER, F_SPLIT(ITEM_KEY_ID,'||',2) AS BUYER_ITEM_NO, F_SPLIT(ITEM_KEY_ID,'||',3) AS KEY_3, F_SPLIT(ITEM_KEY_ID,'||',4) AS KEY_4, F_SPLIT(ITEM_KEY_ID,'||',5) AS KEY_5, (SELECT AGENT_MNG_USER_ID FROM KEP_BURQ_ITEM ITEM WHERE ITEM.BURQ_NO = RFQ.BURQ_NO AND RFQ.ITEM_KEY_ID = ITEM.ITEM_KEY_ID) AS AGENT_MNG_USER_ID, (SELECT MAIN_BUYER FROM KEP_BURQ_ITEM ITEM WHERE ITEM.BURQ_NO = RFQ.BURQ_NO AND RFQ.ITEM_KEY_ID = ITEM.ITEM_KEY_ID) AS MAIN_BUYER FROM KEP_BURQ_RFQ RFQ, (SELECT BURQ_NO, PROJECT_UNIT, PROJECT_NAME FROM KEP_BURQ_MNG) MNG WHERE RFQ.BURQ_NO = MNG.BURQ_NO AND RFQ.AGENT = #{COM_CODE} AND RFQ.STATUS <> 'K3'
AND TO_CHAR(RFQ.ATOS_DATE,'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}
AND RFQ.ATOS_END_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND TO_CHAR(RFQ.STOA_DATE,'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}
AND RFQ.STATUS = #{st_sourcing_status}
AND RFQ.AGENT_TYPE = #{st_agent_type}
) A ) AA WHERE 1=1
AND AA.PROJECT_NAME LIKE '%'||UPPER(#{st_project_name})||'%'
AND AA.BUYER_NAME LIKE '%'||UPPER(#{st_buyer_name})||'%'
AND AA.AGENT_MAKER_NAME LIKE '%'||UPPER(#{st_maker_name})||'%'
AND AA.BURQ_RFQ_NO IN
#{burq_rfq_no}
AND AA.AGENT_DESCRIPTION LIKE '%'||UPPER(#{st_description})||'%'
AND AA.AGENT_SPECIFICATION LIKE '%'||UPPER(#{st_specification})||'%'

mapper.update:

/*updateSellerMpRqBulkQuotationProceStateRfqStatus*/
UPDATE	KEP_BURQ_RFQ
SET		STATUS = 'K2'
WHERE	STATUS <> 'K2'
AND	ATOS_END_DATE < TO_CHAR(SYSDATE,'YYYYMMDD')
AND	AGENT = #{COM_CODE}




AND TO_CHAR(ATOS_DATE,'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}         





AND ATOS_END_DATE BETWEEN #{st_from_date} AND #{st_to_date}   





AND TO_CHAR(STOA_DATE,'YYYYMMDD')  BETWEEN #{st_from_date} AND #{st_to_date}
